def _relaxation(w, traj, times):
    from scipy.optimize import least_squares
    (q, r) = np.linalg.qr(w, mode='reduced')
    target = q.T @ traj

    def basis(rates):
        return -np.expm1(-np.outer(rates, times))

    def residual(rates):
        f = basis(rates)
        return (_fit(f.T, target.T).T @ f - target).ravel()
    fit = least_squares(residual, [0.4, 1.8], bounds=(0.0001, 20.0), ftol=1e-11, gtol=1e-11, xtol=1e-11)
    f = basis(np.sort(fit.x))
    return _fit(r, _fit(f.T, target.T).T) @ f

def _panel_operators(panel):
    from scipy.optimize import least_squares
    u = np.asarray(panel['u'], dtype=float)

    def f1(x, p):
        return np.c_[_affine(x), np.arctan(p[0] * x), np.sin(p[1] * x)]

    def f2(x, p):
        return _affine(x + p[1] * np.cos(p[0] * x))

    def project(fun, key, start, bounds):
        v = np.asarray(panel[key], dtype=float)

        def residual(p):
            d = fun(u, p)
            return (d @ _fit(d, v) - v).ravel()
        p = least_squares(residual, start, bounds=bounds).x
        bet = _fit(fun(u, p), v)
        return lambda x: fun(x, p) @ bet
    return (project(f1, 'v1', [4.4, 2.58], ([1.0, 1.0], [8.0, 5.0])), project(f2, 'v2', [1.28, -0.65], ([0.6, -1.4], [2.2, -0.1])))
